<?php
namespace AutoDealership\Portal;
defined('ABSPATH') || exit;

final class PortalAdmin {
	public static function conversations():void {
		if(!PortalAccess::staff()){wp_die('Forbidden','',array('response'=>403));}
		echo '<div class="wrap adc-portal adc-p-admin"><h1>'.esc_html(PortalAccess::t('محادثات العملاء','Customer conversations')).'</h1>';Portal::flash();
		if(!PortalAccess::ready()){echo '<div class="notice notice-warning"><p>'.esc_html(PortalAccess::t('المراسلات متوقفة أو تحديث قاعدة البيانات لم يكتمل.','Messaging is disabled or the database upgrade is incomplete.')).'</p></div>';}else{
			if(!isset($_GET['thread'])){echo '<form method="get" class="adc-p-filters"><input type="hidden" name="page" value="adc-conversations"><label>'.esc_html(PortalAccess::t('الحالة','Status')).'<select name="status">';foreach(array(''=>'جميع الحالات','staff'=>'بانتظار الموظف','customer'=>'بانتظار العميل','closed'=>'مغلقة') as $status=>$label){echo '<option value="'.esc_attr($status).'" '.selected($_GET['status']??'',$status,false).'>'.esc_html($status?PortalAccess::label($status):PortalAccess::t('جميع الحالات','All statuses')).'</option>';}echo '</select></label><label>'.esc_html(PortalAccess::t('الإسناد','Assignment')).'<select name="owner">';foreach(array(-1=>PortalAccess::t('جميع المحادثات','All conversations'),0=>PortalAccess::t('غير مسند','Unassigned'),get_current_user_id()=>PortalAccess::t('مسند إليّ','Assigned to me')) as $owner=>$label){echo '<option value="'.(int)$owner.'" '.selected($_GET['owner']??-1,$owner,false).'>'.esc_html($label).'</option>';}echo '</select></label>';PortalView::branches(absint($_GET['branch']??0),true);PortalView::button('تصفية','Filter','is-secondary');echo '</form>';}
			PortalView::messages(true);
		}
		if(current_user_can('manage_options')){self::settings();}echo '</div>';
	}
	public static function settings():void {
		$s=PortalAccess::settings();$migration=(array)get_option('adc_portal_migration',array());echo '<details class="adc-p-card"><summary>'.esc_html(PortalAccess::t('إعدادات حساب العميل والمراسلات','Customer account & messaging settings')).'</summary><p>'.esc_html(PortalAccess::t('تتحكم هذه الإعدادات في الواجهة الجديدة وإشعاراتها. تعطيل الواجهة يعيد عرض الحساب السابق ويحفظ السجلات. رسائل تأكيد الحساب والنشرة لا تتأثر.','These settings control the new account experience and its notifications. Disabling the portal restores the previous account view and preserves history. Account and newsletter confirmation emails are unaffected.')).'</p>';Portal::form('settings','messages',array(),true);
		foreach(array('enabled'=>['تفعيل لوحة العميل والمحادثات والتقييمات','Enable the customer portal, conversations and reviews'],'mail'=>['إرسال إشعار بريد عند ورود رسالة أو تحديث مراجعة التقييم','Email notifications for new messages and review decisions']) as $key=>$labels){echo '<label class="adc-p-check"><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked(!empty($s[$key]),true,false).'>'.esc_html(PortalAccess::t(...$labels)).'</label>';}
		PortalView::button('حفظ الإعدادات','Save settings');echo '</form><p class="adc-p-help">'.esc_html(PortalAccess::t('تُنقل الطلبات المرتبطة بحسابات على دفعات تلقائيًا أثناء استخدام الإدارة، دون رسائل تاريخية ودون ربط حساب بمجرد تشابه البريد.','Account-linked requests are imported in batches while using administration, without historical notifications or linking accounts by matching email.')).'</p><p>'.esc_html(PortalAccess::t('ترحيل الرسائل: ','Enquiry import: ').(int)($migration['message']??0).' · '.PortalAccess::t('ترحيل الحجوزات: ','Booking import: ').(int)($migration['booking']??0)).'</p></details>';
	}
	public static function reviews():void {
		if(!PortalAccess::cap('adc_moderate_reviews')){wp_die('Forbidden','',array('response'=>403));}echo '<div class="wrap adc-portal adc-p-admin"><h1>'.esc_html(PortalAccess::t('مراجعة تقييمات العملاء','Customer review moderation')).'</h1><p>'.esc_html(PortalAccess::t('راجع النص والاسم قبل النشر. موافقة النشر إلزامية، ولا يُعد تأكيد البريد إثبات شراء. سبب القرار أدناه ظاهر للعميل؛ لا تكتب فيه ملاحظات داخلية.','Review the text and name before publishing. Publication consent is required, and email confirmation does not prove a purchase. The decision reason below is visible to the customer; do not include internal notes.')).'</p>';Portal::flash();
		$status=isset($_GET['status'])&&is_string($_GET['status'])?sanitize_key($_GET['status']):'pending';$page=max(1,absint($_GET['portal_page']??1));echo '<form method="get" class="adc-p-filters"><input type="hidden" name="page" value="adc-customer-reviews"><label>'.esc_html(PortalAccess::t('الحالة','Status')).'<select name="status">';foreach(array('pending','published','rejected','hidden','withdrawn','') as $value){echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html($value?PortalAccess::label($value):PortalAccess::t('جميع الحالات','All statuses')).'</option>';}echo '</select></label>';PortalView::button('تصفية','Filter','is-secondary');echo '</form>';
		$rows=Reviews::moderation_list($page,$status);if(!$rows){PortalView::empty('لا توجد تقييمات ضمن هذا الاختيار.','No reviews match this filter.');}
		$branches=array_column(PortalAccess::branches(),'name','id');
		foreach(array_slice($rows,0,20) as $row){echo '<article class="adc-p-card"><header class="adc-p-card-head"><div><h2>'.esc_html($row['display_name']).' · '.(int)$row['rating'].'/5</h2><small>'.esc_html(($branches[$row['branch_id']]??PortalAccess::t('فرع غير متاح','Unavailable branch')).' · #'.$row['id']).'</small></div>';PortalView::badge($row['status']);echo '</header><div class="adc-p-review-versions"><section><h3>'.esc_html(PortalAccess::t('النسخة المطلوب مراجعتها','Submitted version')).'</h3><p lang="'.esc_attr($row['locale']).'" dir="'.('ar'===$row['locale']?'rtl':'ltr').'">'.nl2br(esc_html($row['body'])).'</p></section>';
			if($row['public_version']&&$row['public_version']!==$row['current_version']){$old=Reviews::version((int)$row['public_version']);if($old){echo '<section><h3>'.esc_html(PortalAccess::t('النسخة المنشورة حاليًا','Currently published version')).'</h3><strong>'.esc_html($old['display_name']).' · '.(int)$old['rating'].'/5</strong><p>'.nl2br(esc_html($old['body'])).'</p></section>';}}echo '</div>';
			if($row['consent']&&'withdrawn'!==$row['status']){Portal::form('moderate','reviews',array('id'=>$row['id'],'version'=>$row['current_version'],'revision'=>$row['revision']),true);echo '<label>'.esc_html(PortalAccess::t('سبب القرار — يظهر للعميل','Decision reason — visible to the customer')).'<textarea name="reason" rows="2" maxlength="500"></textarea></label><label>'.esc_html(PortalAccess::t('القرار','Decision')).'<select name="decision">';if(PortalAccess::cap('adc_publish_reviews')){echo '<option value="publish">'.esc_html(PortalAccess::t('اعتماد ونشر النسخة الحالية','Approve and publish current version')).'</option>';}echo '<option value="reject">'.esc_html(PortalAccess::t('عدم اعتماد — يتطلب سببًا','Reject — reason required')).'</option><option value="hide">'.esc_html(PortalAccess::t('إخفاء من الموقع','Hide from the website')).'</option></select></label>';PortalView::button('تطبيق القرار','Apply decision');echo '</form>';}echo '</article>';
		}
		PortalView::pagination($page,count($rows)>20,add_query_arg('status',$status,admin_url('admin.php?page=adc-customer-reviews')));echo '</div>';
	}
}
